ALTER TABLE memberships ADD COLUMN consultant_verified INTEGER NOT NULL DEFAULT 0;
ALTER TABLE memberships ADD COLUMN consultant_review_reference TEXT NOT NULL DEFAULT '';
ALTER TABLE memberships ADD COLUMN denied_permissions TEXT NOT NULL DEFAULT '[]';
ALTER TABLE memberships ADD COLUMN care_area_restricted INTEGER NOT NULL DEFAULT 0;
ALTER TABLE memberships ADD COLUMN care_area_ids TEXT NOT NULL DEFAULT '[]';
ALTER TABLE memberships ADD COLUMN access_policy_version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE care_areas (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), branch_id TEXT NOT NULL REFERENCES branches(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('outpatient','ward','observation')), active INTEGER NOT NULL DEFAULT 1, UNIQUE(branch_id,name));
CREATE TABLE care_admissions (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), organization_id TEXT NOT NULL REFERENCES organizations(id), branch_id TEXT NOT NULL REFERENCES branches(id), care_area_id TEXT NOT NULL REFERENCES care_areas(id), kind TEXT NOT NULL CHECK(kind IN ('inpatient','observation')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended')), active_key TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, ended_at TEXT, end_reason TEXT, request_key TEXT UNIQUE NOT NULL, request_payload TEXT NOT NULL);
CREATE INDEX admissions_area ON care_admissions(organization_id,care_area_id,status);
CREATE TABLE admission_team_members (id TEXT PRIMARY KEY, admission_id TEXT NOT NULL REFERENCES care_admissions(id), user_id TEXT NOT NULL REFERENCES users(id), duty TEXT NOT NULL CHECK(duty IN ('doctor','nurse','medication')), active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(admission_id,user_id));
ALTER TABLE care_responsibilities ADD COLUMN admission_id TEXT REFERENCES care_admissions(id);
ALTER TABLE care_visits ADD COLUMN care_area_id TEXT REFERENCES care_areas(id);
CREATE TABLE consultant_referrals (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), organization_id TEXT NOT NULL REFERENCES organizations(id), branch_id TEXT NOT NULL REFERENCES branches(id), from_user_id TEXT NOT NULL REFERENCES users(id), consultant_id TEXT NOT NULL REFERENCES users(id), source_encounter_id TEXT NOT NULL REFERENCES encounters(id), source_version INTEGER NOT NULL, source_scope TEXT NOT NULL DEFAULT 'general', response_encounter_id TEXT REFERENCES encounters(id), visit_id TEXT REFERENCES care_visits(id), kind TEXT NOT NULL CHECK(kind IN ('advice','transfer')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','scheduled','declined','cancelled','completed')), scheduled_at TEXT, accepted_at TEXT, decline_reason TEXT, pending_key TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, request_key TEXT UNIQUE NOT NULL, request_payload TEXT NOT NULL);
CREATE INDEX referrals_inbox ON consultant_referrals(organization_id,consultant_id,status,created_at);
CREATE TABLE care_workflow_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), patient_id TEXT REFERENCES patients(id), object_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX care_workflow_history ON care_workflow_events(object_id,created_at);
